#!/usr/bin/env python3
"""
benchmark.py

Multi-API LLM benchmark harness with SSE streaming TTFT measurement.

Requirements implemented:
- Chat Completions API: POST /v1/chat/completions
- Responses API: POST /v1/responses
- Per-model config loaded from JSON
- TTFT measured from immediately before HTTP request to first non-empty content delta
- Total response time measured until stream ends
- Parallel execution via ThreadPoolExecutor
- stdlib only: urllib.request for HTTP, manual SSE parsing
- Robust per-model error handling
- Python 3.9+
"""

import argparse
import concurrent.futures
import datetime
import json
import os
import socket
import sys
import urllib.error
import urllib.request
import uuid

from time import perf_counter
from typing import Any, Dict, Iterable, List, Optional, Tuple


PROMPT = "Reply with exactly one sentence about the color blue."
DEFAULT_OUTPUT = "benchmark_results.json"


def utc_now_iso() -> str:
    return datetime.datetime.now(datetime.timezone.utc).isoformat()


def ms(seconds: float) -> float:
    return round(seconds * 1000.0, 3)


def truncate(text: str, limit: int = 300) -> str:
    if len(text) <= limit:
        return text
    return text[: limit - 3] + "..."


def load_json_file(path: str) -> Dict[str, Any]:
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def save_json_file(path: str, payload: Dict[str, Any]) -> None:
    with open(path, "w", encoding="utf-8") as f:
        json.dump(payload, f, indent=2, ensure_ascii=False)
        f.write("\n")


def load_models(config_path: str) -> List[Dict[str, Any]]:
    data = load_json_file(config_path)
    if not isinstance(data, dict):
        raise ValueError("Config root must be a JSON object.")
    models = data.get("models")
    if not isinstance(models, list):
        raise ValueError('Config must contain a "models" array.')
    return models


def build_endpoint_url(base_url: str, api_type: str) -> str:
    base = str(base_url).rstrip("/")
    if api_type == "chat_completions":
        return base + "/v1/chat/completions"
    if api_type == "responses":
        return base + "/v1/responses"
    raise ValueError('Unsupported api_type: expected "chat_completions" or "responses".')


def build_payload(model: Dict[str, Any], prompt: str) -> Dict[str, Any]:
    model_id = model["id"]
    api_type = model["api_type"]

    if api_type == "chat_completions":
        payload = {
            "model": model_id,
            "messages": [{"role": "user", "content": prompt}],
            "stream": True,
        }
    elif api_type == "responses":
        payload = {
            "model": model_id,
            "input": prompt,
            "stream": True,
        }
    else:
        raise ValueError('Unsupported api_type: expected "chat_completions" or "responses".')

    if "temperature" in model and model["temperature"] is not None:
        payload["temperature"] = model["temperature"]
    if "max_tokens" in model and model["max_tokens"] is not None:
        payload["max_tokens"] = model["max_tokens"]

    return payload


def build_headers(model: Dict[str, Any]) -> Dict[str, str]:
    headers = {
        "Content-Type": "application/json",
        "Accept": "text/event-stream",
        "User-Agent": "benchmark-harness/1.0",
    }

    api_key_env = model.get("api_key_env")
    api_key = None
    if api_key_env:
        api_key = os.environ.get(str(api_key_env))
        if not api_key:
            raise ValueError("Missing API key in environment variable: %s" % api_key_env)

    auth_header = model.get("auth_header", "Authorization")
    auth_prefix = model.get("auth_prefix")
    if auth_prefix is None and str(auth_header).lower() == "authorization":
        auth_prefix = "Bearer "
    elif auth_prefix is None:
        auth_prefix = ""

    if api_key:
        headers[str(auth_header)] = str(auth_prefix) + api_key

    extra_headers = model.get("headers")
    if extra_headers is not None:
        if not isinstance(extra_headers, dict):
            raise ValueError('Optional model field "headers" must be a JSON object.')
        for key, value in extra_headers.items():
            headers[str(key)] = str(value)

    return headers


def iter_sse_data(response: Any) -> Iterable[str]:
    """
    Yield SSE event payloads from a streaming HTTP response.
    Only `data:` lines are collected; events are emitted on blank lines.
    """
    data_lines: List[str] = []

    while True:
        raw = response.readline()
        if not raw:
            if data_lines:
                yield "\n".join(data_lines)
            break

        line = raw.decode("utf-8", errors="replace").rstrip("\r\n")

        if line == "":
            if data_lines:
                yield "\n".join(data_lines)
                data_lines = []
            continue

        if line.startswith(":"):
            continue

        if line.startswith("data:"):
            value = line[5:]
            if value.startswith(" "):
                value = value[1:]
            data_lines.append(value)


def extract_chat_delta(event: Dict[str, Any]) -> Optional[str]:
    choices = event.get("choices")
    if not isinstance(choices, list):
        return None

    for choice in choices:
        if not isinstance(choice, dict):
            continue
        delta = choice.get("delta")
        if not isinstance(delta, dict):
            continue

        content = delta.get("content")
        if isinstance(content, str):
            return content

        # Extra compatibility for content-part arrays.
        if isinstance(content, list):
            parts: List[str] = []
            for part in content:
                if isinstance(part, dict):
                    text = part.get("text")
                    if isinstance(text, str):
                        parts.append(text)
            if parts:
                return "".join(parts)

    return None


def extract_responses_delta(event: Dict[str, Any]) -> Optional[str]:
    event_type = event.get("type")

    if event_type == "content_block_delta":
        delta = event.get("delta")
        if isinstance(delta, dict):
            text = delta.get("text")
            if isinstance(text, str):
                return text

    # Optional compatibility with other responses-style stream shapes.
    if event_type == "response.output_text.delta":
        delta = event.get("delta")
        if isinstance(delta, str):
            return delta
        if isinstance(delta, dict):
            text = delta.get("text")
            if isinstance(text, str):
                return text

    return None


def extract_delta_text(api_type: str, event: Dict[str, Any]) -> Optional[str]:
    if api_type == "chat_completions":
        return extract_chat_delta(event)
    if api_type == "responses":
        return extract_responses_delta(event)
    return None


def normalize_first_token(text: str) -> str:
    stripped = text.strip()
    return stripped if stripped else text


def make_error_result(model: Dict[str, Any], error: str, total_ms: Optional[float] = None) -> Dict[str, Any]:
    return {
        "model_id": model.get("id"),
        "api_type": model.get("api_type"),
        "status": "error",
        "ttft_ms": None,
        "total_ms": total_ms,
        "first_token": None,
        "full_response": None,
        "error": error,
    }


def benchmark_model(model: Dict[str, Any], prompt: str, timeout: float) -> Dict[str, Any]:
    op_start = perf_counter()
    request_start: Optional[float] = None

    base_result = {
        "model_id": model.get("id"),
        "api_type": model.get("api_type"),
        "status": "error",
        "ttft_ms": None,
        "total_ms": None,
        "first_token": None,
        "full_response": None,
        "error": None,
    }

    try:
        model_id = model["id"]
        api_type = model["api_type"]
        base_url = model["base_url"]

        url = build_endpoint_url(base_url, api_type)
        payload = build_payload(model, prompt)
        headers = build_headers(model)

        data = json.dumps(payload).encode("utf-8")
        request = urllib.request.Request(url=url, data=data, headers=headers, method="POST")

        first_token_time: Optional[float] = None
        first_token: Optional[str] = None
        parts: List[str] = []

        request_start = perf_counter()
        with urllib.request.urlopen(request, timeout=timeout) as response:
            for sse_data in iter_sse_data(response):
                if sse_data == "[DONE]":
                    break
                if not sse_data:
                    continue

                try:
                    event = json.loads(sse_data)
                except json.JSONDecodeError as e:
                    raise ValueError("SSE JSON parse error: %s" % e.msg)

                delta_text = extract_delta_text(api_type, event)
                if delta_text is None or delta_text == "":
                    continue

                if first_token_time is None:
                    first_token_time = perf_counter()
                    first_token = normalize_first_token(delta_text)

                parts.append(delta_text)

        end = perf_counter()
        base_result["total_ms"] = ms(end - request_start)

        if first_token_time is None:
            base_result["error"] = "No content received before stream ended"
            return base_result

        full_response = "".join(parts)
        base_result["status"] = "ok"
        base_result["ttft_ms"] = ms(first_token_time - request_start)
        base_result["first_token"] = first_token
        base_result["full_response"] = full_response
        base_result["error"] = None
        return base_result

    except urllib.error.HTTPError as e:
        detail = ""
        try:
            body = e.read().decode("utf-8", errors="replace").strip()
            if body:
                detail = ": " + truncate(body)
        except Exception:
            pass
        base_result["error"] = "HTTP %s %s%s" % (e.code, e.reason, detail)

    except urllib.error.URLError as e:
        reason = e.reason
        if isinstance(reason, socket.timeout):
            base_result["error"] = "Connection timeout after %dms" % int(timeout * 1000)
        else:
            base_result["error"] = "Connection error: %s" % reason

    except socket.timeout:
        base_result["error"] = "Connection timeout after %dms" % int(timeout * 1000)

    except TimeoutError:
        base_result["error"] = "Connection timeout after %dms" % int(timeout * 1000)

    except ValueError as e:
        base_result["error"] = str(e)

    except KeyError as e:
        base_result["error"] = "Missing required model config field: %s" % e.args[0]

    except Exception as e:
        base_result["error"] = "%s: %s" % (e.__class__.__name__, str(e))

    end = perf_counter()
    base_time = request_start if request_start is not None else op_start
    base_result["total_ms"] = ms(end - base_time)
    return base_result


def build_summary(results: List[Dict[str, Any]]) -> Dict[str, Any]:
    ok_results = [r for r in results if r.get("status") == "ok" and isinstance(r.get("ttft_ms"), (int, float))]
    total = len(results)
    ok = len([r for r in results if r.get("status") == "ok"])
    errors = total - ok

    summary: Dict[str, Any] = {
        "total": total,
        "ok": ok,
        "errors": errors,
        "avg_ttft_ms": None,
        "fastest_model": None,
        "slowest_model": None,
    }

    if ok_results:
        avg_ttft = sum(float(r["ttft_ms"]) for r in ok_results) / len(ok_results)
        fastest = min(ok_results, key=lambda r: float(r["ttft_ms"]))
        slowest = max(ok_results, key=lambda r: float(r["ttft_ms"]))
        summary["avg_ttft_ms"] = round(avg_ttft, 3)
        summary["fastest_model"] = fastest.get("model_id")
        summary["slowest_model"] = slowest.get("model_id")

    return summary


def run_benchmark(
    models: List[Dict[str, Any]],
    prompt: str,
    timeout: float,
    workers: int,
) -> List[Dict[str, Any]]:
    if not models:
        return []

    results: List[Optional[Dict[str, Any]]] = [None] * len(models)
    max_workers = max(1, int(workers))

    with concurrent.futures.ThreadPoolExecutor(max_workers=max_workers) as executor:
        future_to_index = {
            executor.submit(benchmark_model, model, prompt, timeout): idx
            for idx, model in enumerate(models)
        }

        for future in concurrent.futures.as_completed(future_to_index):
            idx = future_to_index[future]
            model = models[idx]
            try:
                results[idx] = future.result()
            except Exception as e:
                # Safety net: benchmark_model already handles errors, but never let one future crash the run.
                results[idx] = make_error_result(
                    model,
                    "Unhandled worker error: %s: %s" % (e.__class__.__name__, str(e)),
                )

    return [r for r in results if r is not None]


def parse_args(argv: Optional[List[str]] = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="LLM benchmark harness with SSE TTFT measurement")
    parser.add_argument("--config", required=True, help="Path to model config JSON")
    parser.add_argument("--output", default=DEFAULT_OUTPUT, help="Output JSON path")
    parser.add_argument("--timeout", type=float, default=30.0, help="Per-model timeout in seconds")
    parser.add_argument("--workers", type=int, default=1, help="Parallel worker count")
    return parser.parse_args(argv)


def main(argv: Optional[List[str]] = None) -> int:
    args = parse_args(argv)

    try:
        models = load_models(args.config)
    except FileNotFoundError:
        print("Config file not found: %s" % args.config, file=sys.stderr)
        return 2
    except json.JSONDecodeError as e:
        print("Invalid JSON in config file: %s" % e, file=sys.stderr)
        return 2
    except Exception as e:
        print("Failed to load config: %s" % e, file=sys.stderr)
        return 2

    results = run_benchmark(
        models=models,
        prompt=PROMPT,
        timeout=args.timeout,
        workers=args.workers,
    )

    output = {
        "run_id": str(uuid.uuid4()),
        "timestamp": utc_now_iso(),
        "prompt": PROMPT,
        "results": results,
        "summary": build_summary(results),
    }

    try:
        save_json_file(args.output, output)
    except Exception as e:
        print("Failed to write output file: %s" % e, file=sys.stderr)
        return 2

    print("Saved benchmark results to %s" % args.output)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
